using System;using System.Reflection;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Rootborn.UI.Modern;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryIconFallbackTests{[Test]public void OptionalLegacySpriteSurvivesMissingThemeAndReturnsAfterThemeRelease(){var current=UrbanUiThemeRuntime.Current;var go=new GameObject("icon",typeof(RectTransform),typeof(Image));var texture=new Texture2D(2,2);var fallback=Sprite.Create(texture,new Rect(0,0,2,2),new Vector2(.5f,.5f));try{Publish(null);var icon=go.AddComponent<UrbanUiIcon>();var method=typeof(UrbanUiIcon).GetMethod("ConfigureWithFallback",new[]{typeof(string),typeof(Sprite)});Assert.That(method,Is.Not.Null,"Inventory may keep its loaded vendor icon while theme is missing or released");method.Invoke(icon,new object[]{"inventory-all",fallback});var image=go.GetComponent<Image>();Assert.That(image.sprite,Is.SameAs(fallback));Assert.That(image.enabled,Is.True);Publish(AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset"));Assert.That(image.sprite.name,Is.EqualTo("student_backpack"));Publish(null);Assert.That(image.sprite,Is.SameAs(fallback));Assert.That(image.enabled,Is.True);Assert.That(image.raycastTarget,Is.False);}finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(fallback);UnityEngine.Object.DestroyImmediate(texture);Publish(current);}}static void Publish(UrbanUiThemeDefinition theme){typeof(UrbanUiThemeRuntime).GetProperty("Current").GetSetMethod(true).Invoke(null,new object[]{theme});var f=typeof(UrbanUiThemeRuntime).GetField("Changed",BindingFlags.NonPublic|BindingFlags.Static);(f.GetValue(null)as Action)?.Invoke();}}}
